1	package net.officefloor.hq.app.invoices;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import net.officefloor.hq.app.Audit;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.jdbc.core.RowMapper;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * Business logic for invoices. Invoices are always viewed in the context of their project, so the
14	 * list is scoped by project id. The derived total the UI shows is computed by the front-end from the
15	 * returned rows; this service just surfaces the project's invoices in a stable order. Marking an
16	 * invoice paid flips its status and records an audit entry so the action can be checked later.
17	 */
18	@Service
19	public class InvoiceService {
20	
21	    // An invoice's amount minus whatever has been paid against it is what is still left to pay.
22	    private static final String DUE_AWARE_SELECT =
23	            "SELECT i.id, i.project_id, i.amount, i.status, i.issued_date, i.due_date, "
24	                    + "i.amount - COALESCE((SELECT SUM(p.amount) FROM payments p "
25	                    + "WHERE p.invoice_id = i.id), 0) AS due_amount FROM invoices i ";
26	
27	    private static final RowMapper<InvoiceView> INVOICE_MAPPER = (rs, i) -> {
28	        BigDecimal amount = rs.getBigDecimal("amount");
29	        BigDecimal dueAmount = rs.getBigDecimal("due_amount");
30	        return new InvoiceView(rs.getLong("id"), rs.getLong("project_id"), amount,
31	                deriveStatus(rs.getString("status"), amount, dueAmount),
32	                rs.getDate("issued_date").toLocalDate().toString(),
33	                rs.getDate("due_date").toLocalDate().toString(), dueAmount);
34	    };
35	
36	    /**
37	     * The status we show is worked out from the payments, not flipped by hand: an invoice reads PAID
38	     * once its payments cover the amount, PARTIAL once some (but not all) has been paid, and otherwise
39	     * keeps its stored lifecycle status (DRAFT/SENT).
40	     */
41	    private static String deriveStatus(String stored, BigDecimal amount, BigDecimal dueAmount) {
42	        BigDecimal paid = amount.subtract(dueAmount);
43	        if (paid.signum() <= 0) {
44	            return stored;
45	        }
46	        return dueAmount.signum() <= 0 ? "PAID" : "PARTIAL";
47	    }
48	
49	    private final InvoiceRepository repository;
50	    private final LineItemRepository lineItemRepository;
51	    private final PaymentRepository paymentRepository;
52	    private final JdbcTemplate jdbc;
53	    private final Audit audit;
54	
55	    public InvoiceService(InvoiceRepository repository, LineItemRepository lineItemRepository,
56	            PaymentRepository paymentRepository, JdbcTemplate jdbc, Audit audit) {
57	        this.repository = repository;
58	        this.lineItemRepository = lineItemRepository;
59	        this.paymentRepository = paymentRepository;
60	        this.jdbc = jdbc;
61	        this.audit = audit;
62	    }
63	
64	    /** Every invoice across all projects; narrowed to a single lifecycle stage when {@code status} is given. */
65	    @Transactional(readOnly = true)
66	    public List<AllInvoiceView> listAll(String status) {
67	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
68	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
69	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
70	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
71	        if (status == null || status.isBlank()) {
72	            return jdbc.query(base + "ORDER BY i.id ASC", mapper);
73	        }
74	        return jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC", mapper, status.trim());
75	    }
76	
77	    /**
78	     * One page of the cross-project invoice list. The list is large, so it is served a page at a
79	     * time in id order, optionally narrowed to a lifecycle stage. {@code page} is 1-based and
80	     * {@code size} is the page size; both are clamped to sane minimums. The returned view carries
81	     * the page's rows plus the paging metadata (page served, total pages, total rows).
82	     */
83	    @Transactional(readOnly = true)
84	    public AllInvoicesPageView listAllPaged(String status, int page, int size) {
85	        int pageSize = Math.max(1, size);
86	        boolean filtered = status != null && !status.isBlank();
87	        String stage = filtered ? status.trim() : null;
88	
89	        String countSql = "SELECT COUNT(*) FROM invoices i"
90	                + (filtered ? " WHERE i.status = ?" : "");
91	        long total = filtered
92	                ? jdbc.queryForObject(countSql, Long.class, stage)
93	                : jdbc.queryForObject(countSql, Long.class);
94	
95	        int pageCount = total == 0 ? 1 : (int) ((total + pageSize - 1) / pageSize);
96	        int current = Math.min(Math.max(1, page), pageCount);
97	        int offset = (current - 1) * pageSize;
98	
99	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
100	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
101	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
102	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
103	        List<AllInvoiceView> items = filtered
104	                ? jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC LIMIT ? OFFSET ?",
105	                        mapper, stage, pageSize, offset)
106	                : jdbc.query(base + "ORDER BY i.id ASC LIMIT ? OFFSET ?",
107	                        mapper, pageSize, offset);
108	        return new AllInvoicesPageView(items, current, pageCount, total);
109	    }
110	
111	    @Transactional(readOnly = true)
112	    public List<InvoiceView> listForProject(Long projectId) {
113	        return jdbc.query(
114	                DUE_AWARE_SELECT + "WHERE i.project_id = ? ORDER BY i.id ASC",
115	                INVOICE_MAPPER, projectId);
116	    }
117	
118	    @Transactional(readOnly = true)
119	    public List<InvoiceView> listForProjectByDueDate(Long projectId) {
120	        return jdbc.query(
121	                DUE_AWARE_SELECT + "WHERE i.project_id = ? ORDER BY i.due_date ASC, i.id ASC",
122	                INVOICE_MAPPER, projectId);
123	    }
124	
125	    @Transactional
126	    public InvoiceView create(Long projectId, BigDecimal amount) {
127	        if (projectId == null) {
128	            throw new IllegalArgumentException("An invoice requires a project");
129	        }
130	        if (amount == null) {
131	            throw new IllegalArgumentException("An invoice requires an amount");
132	        }
133	        if (amount.signum() <= 0) {
134	            throw new IllegalArgumentException("An invoice amount must be greater than zero");
135	        }
136	        Invoice invoice = new Invoice();
137	        invoice.setProjectId(projectId);
138	        invoice.setAmount(amount);
139	        // A new invoice goes out today and is due 30 days later.
140	        LocalDate issued = LocalDate.now();
141	        invoice.setIssuedDate(issued);
142	        invoice.setDueDate(issued.plusDays(30));
143	        Invoice saved = repository.save(invoice);
144	        // A brand-new invoice has had nothing paid against it yet, so the whole amount is due.
145	        return new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(),
146	                saved.getStatus(), saved.getIssuedDate().toString(), saved.getDueDate().toString(),
147	                saved.getAmount());
148	    }
149	
150	    @Transactional
151	    public InvoiceView send(Long invoiceId) {
152	        if (invoiceId == null) {
153	            throw new IllegalArgumentException("An invoice id is required");
154	        }
155	        InvoiceView current = find(invoiceId);
156	        if (!"DRAFT".equals(current.getStatus())) {
157	            throw new IllegalStateException("Only a draft invoice can be sent");
158	        }
159	        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", invoiceId);
160	        InvoiceView invoice = find(invoiceId);
161	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount="
162	                + invoice.getAmount().setScale(2));
163	        return invoice;
164	    }
165	
166	    @Transactional
167	    public InvoiceView pay(Long invoiceId) {
168	        if (invoiceId == null) {
169	            throw new IllegalArgumentException("An invoice id is required");
170	        }
171	        InvoiceView current = find(invoiceId);
172	        // Payment is only allowed once an invoice has been sent.
173	        if (!"SENT".equals(current.getStatus())) {
174	            throw new IllegalStateException("An invoice can only be paid once it has been sent");
175	        }
176	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", invoiceId);
177	        InvoiceView invoice = find(invoiceId);
178	        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount="
179	                + invoice.getAmount().setScale(2));
180	        return invoice;
181	    }
182	
183	    /** The line items of an invoice, in the order they were added. */
184	    @Transactional(readOnly = true)
185	    public List<LineItemView> listLineItems(Long invoiceId) {
186	        return jdbc.query(
187	                "SELECT id, invoice_id, description, qty, unit_price FROM line_items WHERE invoice_id = ? ORDER BY id ASC",
188	                (rs, i) -> new LineItemView(rs.getLong("id"), rs.getLong("invoice_id"),
189	                        rs.getString("description"), rs.getInt("qty"),
190	                        rs.getBigDecimal("unit_price")),
191	                invoiceId);
192	    }
193	
194	    /**
195	     * Add one line item to an invoice, then re-derive the invoice's amount as the sum of each line's
196	     * quantity times unit price so the stored total stays in step. Returns the invoice's line items.
197	     */
198	    @Transactional
199	    public List<LineItemView> addLineItem(Long invoiceId, NewLineItem body) {
200	        if (invoiceId == null) {
201	            throw new IllegalArgumentException("An invoice id is required");
202	        }
203	        if (body == null || body.getDescription() == null || body.getDescription().isBlank()) {
204	            throw new IllegalArgumentException("A line item requires a description");
205	        }
206	        if (body.getQty() == null || body.getQty() <= 0) {
207	            throw new IllegalArgumentException("A line item requires a quantity greater than zero");
208	        }
209	        if (body.getUnitPrice() == null || body.getUnitPrice().signum() < 0) {
210	            throw new IllegalArgumentException("A line item requires a unit price that is not negative");
211	        }
212	        LineItem lineItem = new LineItem();
213	        lineItem.setInvoiceId(invoiceId);
214	        lineItem.setDescription(body.getDescription());
215	        lineItem.setQty(body.getQty());
216	        lineItem.setUnitPrice(body.getUnitPrice());
217	        lineItemRepository.save(lineItem);
218	        jdbc.update(
219	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
220	                invoiceId, invoiceId);
221	        return listLineItems(invoiceId);
222	    }
223	
224	    /**
225	     * Remove one line item from an invoice, then re-derive the invoice's amount as the sum of each
226	     * remaining line's quantity times unit price so the stored total stays in step. Returns the
227	     * invoice's remaining line items.
228	     */
229	    @Transactional
230	    public List<LineItemView> removeLineItem(Long invoiceId, Long lineItemId) {
231	        if (invoiceId == null) {
232	            throw new IllegalArgumentException("An invoice id is required");
233	        }
234	        if (lineItemId == null) {
235	            throw new IllegalArgumentException("A line item id is required");
236	        }
237	        jdbc.update("DELETE FROM line_items WHERE id = ? AND invoice_id = ?", lineItemId, invoiceId);
238	        jdbc.update(
239	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
240	                invoiceId, invoiceId);
241	        return listLineItems(invoiceId);
242	    }
243	
244	    /** The payments a client has made on an invoice, in the order they were recorded. */
245	    @Transactional(readOnly = true)
246	    public List<PaymentView> listPayments(Long invoiceId) {
247	        return jdbc.query(
248	                "SELECT id, invoice_id, amount, paid_date FROM payments WHERE invoice_id = ? ORDER BY id ASC",
249	                (rs, i) -> new PaymentView(rs.getLong("id"), rs.getLong("invoice_id"),
250	                        rs.getBigDecimal("amount"), rs.getDate("paid_date").toLocalDate().toString()),
251	                invoiceId);
252	    }
253	
254	    /** Record one payment a client has made against an invoice. Returns the invoice's payments. */
255	    @Transactional
256	    public List<PaymentView> addPayment(Long invoiceId, NewPayment body) {
257	        if (invoiceId == null) {
258	            throw new IllegalArgumentException("An invoice id is required");
259	        }
260	        if (body == null || body.getAmount() == null || body.getAmount().signum() <= 0) {
261	            throw new IllegalArgumentException("A payment requires an amount greater than zero");
262	        }
263	        if (body.getDate() == null || body.getDate().isBlank()) {
264	            throw new IllegalArgumentException("A payment requires a date");
265	        }
266	        Payment payment = new Payment();
267	        payment.setInvoiceId(invoiceId);
268	        payment.setAmount(body.getAmount());
269	        payment.setPaidDate(LocalDate.parse(body.getDate()));
270	        Payment saved = paymentRepository.save(payment);
271	        audit.record("PAYMENT_RECORDED id=" + saved.getId() + " amount="
272	                + body.getAmount().setScale(2));
273	        return listPayments(invoiceId);
274	    }
275	
276	    /** One invoice, with its status worked out from the payments recorded against it. */
277	    @Transactional(readOnly = true)
278	    public InvoiceView get(Long invoiceId) {
279	        if (invoiceId == null) {
280	            throw new IllegalArgumentException("An invoice id is required");
281	        }
282	        return find(invoiceId);
283	    }
284	
285	    private InvoiceView find(Long invoiceId) {
286	        return jdbc.queryForObject(DUE_AWARE_SELECT + "WHERE i.id = ?", INVOICE_MAPPER, invoiceId);
287	    }
288	}
