4	
5	// Opened from a project's invoice row (invoice-open-<id>): instead of typing one figure, you list
6	// the things you are charging for — each with a description, how many, and the price each. The
7	// invoice total is worked out for you as the sum of each line's quantity times unit price. Line
8	// items are scoped to the invoice via /api/invoices/<id>/line-items.
9	type LineItem = {
10	  id: number;
11	  invoiceId: number;
12	  description: string;
13	  qty: number;
14	  unitPrice: number;
15	};
16	
17	// The invoice's status is worked out from its payments (PAID once covered, PARTIAL once part paid),
18	// so we read it back from the server rather than flipping it by hand.
19	type Invoice = {
20	  id: number;
21	  status: string;
22	};
23	
24	export function InvoiceLineItems({
25	  invoiceId,
26	  onBack,
27	}: {
28	  invoiceId: number;
29	  onBack: () => void;
30	}) {
31	  const [lineItems, setLineItems] = useState<LineItem[]>([]);
32	  const [status, setStatus] = useState('');
33	  const [description, setDescription] = useState('');
34	  const [qty, setQty] = useState('');
35	  const [unitPrice, setUnitPrice] = useState('');
36	
37	  async function load() {
38	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
39	    if (res.ok) {
40	      setLineItems(await res.json());
41	    }
42	  }
43	
44	  async function loadInvoice() {
45	    const res = await fetch(`/api/invoices/${invoiceId}`);
46	    if (res.ok) {
47	      const invoice: Invoice = await res.json();
48	      setStatus(invoice.status);
49	    }
50	  }
51	
52	  useEffect(() => {
53	    void load();
54	    void loadInvoice();
55	  }, [invoiceId]);
56	
57	  async function onRemove(lineItemId: number) {
58	    const res = await fetch(
59	      `/api/invoices/${invoiceId}/line-items/${lineItemId}/remove`,
60	      { method: 'POST' },
61	    );
62	    if (res.ok) {
63	      // The endpoint returns the invoice's remaining line items; the total re-derives from them.
64	      setLineItems(await res.json());
65	      // The amount changed, so the status worked out from the payments may have too.
66	      void loadInvoice();
67	    }
68	  }
69	
70	  async function onSubmit(event: FormEvent) {
71	    event.preventDefault();
72	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`, {
73	      method: 'POST',
74	      headers: { 'Content-Type': 'application/json' },
75	      body: JSON.stringify({
76	        description,
77	        qty: Number(qty),
78	        unitPrice: Number(unitPrice),
79	      }),
80	    });
81	    if (res.ok) {
82	      // The endpoint returns the invoice's line items, totals included on re-derive.
83	      setLineItems(await res.json());
84	      // The amount changed, so the status worked out from the payments may have too.
85	      void loadInvoice();
86	      setDescription('');
87	      setQty('');
88	      setUnitPrice('');
89	    }
90	  }
91	
92	  const total = lineItems.reduce((sum, item) => sum + item.qty * Number(item.unitPrice), 0);
93	
94	  return (
95	    <section data-testid="invoice-detail">
96	      <button data-testid="invoice-close" type="button" onClick={onBack}>
97	        Back to invoices
98	      </button>
99	
100	      <p data-testid="invoice-status">{status}</p>
101	
102	      <table data-testid="invoice-lineitems-table">
103	        <thead>
104	          <tr>
105	            <th>Description</th>
