    if (res.ok) {
      setTasks(await res.json());
    }
  }

  useEffect(() => {
    void load();
  }, [projectId]);

  useEffect(() => {
    void loadTasks();
  }, [projectId, taskFilter]);

  // Tick a task off (or back on): toggles OPEN <-> DONE and reloads the list.
  async function onToggleTask(taskId: number) {
