    if (res.ok) {
      await load();
    }
  }

  // Cancel (void) an invoice sent by mistake: it reads VOID and stops counting toward what is owed.
  async function onCancel(invoiceId: number) {
    const res = await fetch(`/api/invoices/${invoiceId}/cancel`, { method: 'POST' });
    if (res.ok) {
      await load();
    }
  }

