          <dt>Invoiced</dt>
          <dd data-testid="project-invoiced">{formatMoney(budget.invoiced)}</dd>
          <dt>Remaining</dt>
          <dd data-testid="project-remaining">{formatMoney(budget.remaining)}</dd>
        </dl>
      )}

      <ProjectTags projectId={projectId} />

